//   - kind 'css' : ctx.filter 의 CSS 필터 함수 (grayscale, sepia, hue-rotate ...)
//   - kind 'svg' : 인라인 SVG <filter> 를 url(#id) 로 참조 (포스터화·엣지검출)
//   - kind 'pixelate' / 'ghost' : drawImage 만으로 처리하는 특수 효과
//   - kind 'none' : 원본
//
// 필터 "강도"는 App 의 렌더 루프에서 필터를 입힌 화면을 원본 위에 반투명(globalAlpha)으로
// 덮는 방식으로 조절한다. 그래서 여기 함수들은 "최대 강도" 문자열만 돌려주면 된다.

export type FilterId =
  | 'none'
  | 'grayscale'
  | 'sepia'
  | 'invert'
  | 'vintage'
  | 'blur'
  | 'warm'
  | 'cool'
  | 'rainbow'
  | 'threshold'
  | 'cartoon'
  | 'neon'
  | 'pixelate'
  | 'ghost';

export type FilterKind = 'none' | 'css' | 'svg' | 'pixelate' | 'ghost';

export interface FilterOption {
  id: FilterId;
  label: string;
  emoji: string;
  kind: FilterKind;
  gradient: string; // 필터 칩 미리보기에 쓰는 CSS 그라데이션
}

export const FILTER_OPTIONS: FilterOption[] = [
  { id: 'none',      label: '원본',     emoji: '🎥', kind: 'none',     gradient: 'linear-gradient(135deg,#64748b,#94a3b8)' },
  { id: 'grayscale', label: '흑백',     emoji: '🌑', kind: 'css',      gradient: 'linear-gradient(135deg,#1f2937,#9ca3af)' },
  { id: 'sepia',     label: '세피아',   emoji: '🟤', kind: 'css',      gradient: 'linear-gradient(135deg,#78350f,#d6a36e)' },
  { id: 'invert',    label: '반전',     emoji: '🔄', kind: 'css',      gradient: 'linear-gradient(135deg,#0ea5e9,#f43f5e)' },
  { id: 'vintage',   label: '빈티지',   emoji: '📷', kind: 'css',      gradient: 'linear-gradient(135deg,#b45309,#fcd34d)' },
  { id: 'blur',      label: '소프트',   emoji: '🌫️', kind: 'css',      gradient: 'linear-gradient(135deg,#a5b4fc,#e0e7ff)' },
  { id: 'warm',      label: '웜톤',     emoji: '🔥', kind: 'css',      gradient: 'linear-gradient(135deg,#f97316,#fbbf24)' },
  { id: 'cool',      label: '쿨톤',     emoji: '❄️', kind: 'css',      gradient: 'linear-gradient(135deg,#2563eb,#22d3ee)' },
  { id: 'rainbow',   label: '무지개',   emoji: '🌈', kind: 'css',      gradient: 'linear-gradient(135deg,#ef4444,#eab308,#22c55e,#3b82f6,#a855f7)' },
  { id: 'threshold', label: '흑백대비', emoji: '🌗', kind: 'css',      gradient: 'linear-gradient(135deg,#000000,#ffffff)' },
  { id: 'cartoon',   label: '만화',     emoji: '🎨', kind: 'svg',      gradient: 'linear-gradient(135deg,#f472b6,#facc15)' },
  { id: 'neon',      label: '네온',     emoji: '⚡', kind: 'svg',      gradient: 'linear-gradient(135deg,#22d3ee,#a855f7)' },
  { id: 'pixelate',  label: '픽셀',     emoji: '🟦', kind: 'pixelate', gradient: 'linear-gradient(135deg,#3b82f6,#1e3a8a)' },
  { id: 'ghost',     label: '고스트',   emoji: '👻', kind: 'ghost',    gradient: 'linear-gradient(135deg,#475569,#cbd5e1)' },
];

// 밝기/대비/채도 보정값 (1 = 기본)
export interface Adjustments {
  brightness: number; // 0.5 ~ 1.5
  contrast: number;   // 0.5 ~ 1.5
  saturation: number; // 0 ~ 2
}

export const DEFAULT_ADJUSTMENTS: Adjustments = {
  brightness: 1,
  contrast: 1,
  saturation: 1,
};

// 밝기·대비·채도 보정을 ctx.filter 문자열로 만든다 (모든 필터에 공통 적용)
export function buildAdjustmentFilter(adjust: Adjustments): string {
  return [
    `brightness(${adjust.brightness})`,
    `contrast(${adjust.contrast})`,
    `saturate(${adjust.saturation})`,
  ].join(' ');
}

// 선택한 필터의 "최대 강도" 효과를 ctx.filter 문자열로 만든다.
// css 계열은 CSS 필터 함수, svg 계열은 인라인 SVG 필터를 url(#id)로 참조한다.
export function buildEffectFilter(filter: FilterOption, frame: number): string {
  switch (filter.id) {
    case 'grayscale':
      return 'grayscale(1)';
    case 'sepia':
      return 'sepia(1)';
    case 'invert':
      return 'invert(1)';
    case 'blur':
      return 'blur(6px)';
    case 'vintage':
      return 'sepia(0.6) contrast(1.15) brightness(1.05) saturate(1.5)';
    case 'warm':
      return 'sepia(0.5) saturate(1.6) hue-rotate(-12deg) brightness(1.05)';
    case 'cool':
      return 'sepia(0.6) hue-rotate(180deg) saturate(1.5) brightness(1.02)';
    case 'threshold':
      return 'grayscale(1) contrast(8)';
    case 'rainbow':
      // 시간에 따라 색상환을 돌려 무지개처럼 색이 흐른다
      return `hue-rotate(${(frame * 3) % 360}deg) saturate(2)`;
    case 'cartoon':
      return 'saturate(1.4) url(#magic-posterize)';
    case 'neon':
      return 'brightness(1.1) url(#magic-edge)';
    default:
      return '';
  }
}

