  label,
  value,
  min,
  max,
  step = 1,
  unit = '%',
  color = '#a855f7',
  disabled = false,
  onChange,
}: ControlSliderProps) {
  const percent = ((value - min) / (max - min)) * 100;
  const trackBackground = `linear-gradient(to right, ${color} 0%, ${color} ${percent}%, rgba(255,255,255,0.12) ${percent}%, rgba(255,255,255,0.12) 100%)`;

