      buffer.height = height;
    }
    const bufferContext = buffer.getContext('2d');
    if (!bufferContext) return;

    context.globalAlpha = 0.2 + strength * 0.55;
    context.drawImage(buffer, 0, 0);
    context.globalAlpha = 1;

    bufferContext.clearRect(0, 0, width, height);
    bufferContext.drawImage(canvas, 0, 0);
  };

  // 비네팅: 가운데는 그대로, 가장자리를 어둡게
  const drawVignette = (
    context: CanvasRenderingContext2D,
    width: number,
    height: number,
    strength: number,
  ) => {
    const gradient = context.createRadialGradient(
      width / 2,
      height / 2,
      Math.min(width, height) * 0.35,
      width / 2,
      height / 2,
      Math.max(width, height) * 0.75,
    );
    gradient.addColorStop(0, 'rgba(0,0,0,0)');
    gradient.addColorStop(1, `rgba(0,0,0,${(0.65 * strength).toFixed(2)})`);
    context.fillStyle = gradient;
    context.fillRect(0, 0, width, height);
  };

  // 촬영 플래시 효과
  const triggerFlash = () => {
    setShowFlash(true);
    window.setTimeout(() => setShowFlash(false), 350);
  };

  // 사진 찍기 — 현재 캔버스를 갤러리에 추가
  const capturePhoto = () => {
    const canvas = canvasRef.current;
    if (!canvas || canvas.width === 0) return;
    const url = canvas.toDataURL('image/png');
    const photo: Photo = {
      id: `${Date.now()}-${Math.round(Math.random() * 1e6)}`,
      url,
      filter: currentFilter.label,
    };
    setPhotos((previous) => [photo, ...previous].slice(0, 18));
    triggerFlash();
  };

  // 셀카 타이머 — 0초면 바로, 아니면 카운트다운 후 촬영
  const handleShutter = () => {
    if (!isStreaming || countdown !== null) return;
    if (timerSeconds === 0) {
      capturePhoto();
      return;
    }
    setCountdown(timerSeconds);
    countdownTimerRef.current = window.setInterval(() => {
      setCountdown((current) => {
        if (current === null) return null;
        if (current <= 1) {
          window.clearInterval(countdownTimerRef.current);
          capturePhoto();
          return null;
        }
        return current - 1;
      });
    }, 1000);
  };

  // 스페이스바로 촬영
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      const tag = (event.target as HTMLElement)?.tagName;
      if (tag === 'INPUT' || tag === 'TEXTAREA') return;
      if (event.code === 'Space') {
        event.preventDefault();
        handleShutter();
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => window.removeEventListener('keydown', onKeyDown);
  });

  // 녹화에 쓸 수 있는 mimeType 고르기
  const pickMimeType = () => {
    const candidates = ['video/webm;codecs=vp9', 'video/webm;codecs=vp8', 'video/webm'];
    for (const candidate of candidates) {
      if (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported(candidate)) {
        return candidate;
      }
    }
    return '';
  };

  // 녹화 시작 — 필터가 적용된 캔버스 화면을 그대로 영상으로 저장
  const startRecording = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const canvasStream = canvas.captureStream(30);
    recordedChunksRef.current = [];
    const mimeType = pickMimeType();

    const recorder = new MediaRecorder(canvasStream, mimeType ? { mimeType } : undefined);
    recorder.ondataavailable = (event) => {
      if (event.data.size > 0) recordedChunksRef.current.push(event.data);
    };
    recorder.onstop = () => {
      const recordedBlob = new Blob(recordedChunksRef.current, { type: 'video/webm' });
      setRecordedUrl((previous) => {
        if (previous) URL.revokeObjectURL(previous);
        return URL.createObjectURL(recordedBlob);
      });
    };
    recorder.start();
    mediaRecorderRef.current = recorder;
    setIsRecording(true);
    setRecordSeconds(0);
    recordTimerRef.current = window.setInterval(() => {
      setRecordSeconds((previous) => previous + 1);
    }, 1000);
  };

  // 녹화 멈춤
  const stopRecording = () => {
    mediaRecorderRef.current?.stop();
    mediaRecorderRef.current = null;
    window.clearInterval(recordTimerRef.current);
    setIsRecording(false);
  };

  // 단일 사진 다운로드
  const downloadPhoto = (photo: Photo) => {
    const link = document.createElement('a');
    link.href = photo.url;
    link.download = `magic-${photo.id}.png`;
    link.click();
  };

  // 전체 사진 다운로드
  const downloadAllPhotos = () => {
    photos.forEach((photo, index) => {
      window.setTimeout(() => downloadPhoto(photo), index * 200);
    });
  };

  const deletePhoto = (id: string) => {
    setPhotos((previous) => previous.filter((photo) => photo.id !== id));
  };

  const resetAdjustments = () => {
    setAdjust({ brightness: 100, contrast: 100, saturation: 100 });
    setIntensity(100);
  };

  const formatTime = (totalSeconds: number) => {
    const minutes = Math.floor(totalSeconds / 60);
    const seconds = totalSeconds % 60;
    return `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`;
  };

  return (
    <div className="relative flex min-h-screen flex-col overflow-x-hidden text-white">
      <GlobalStyles />
      <SvgFilters />

      {/* 움직이는 그라데이션 배경 */}
      <div
        className="fixed inset-0 -z-10"
        style={{
