          animation: 'bg-pan 22s ease infinite',
        }}
      />
      <div className="pointer-events-none fixed -left-32 -top-32 -z-10 h-96 w-96 rounded-full bg-fuchsia-600/20 blur-3xl" />
      <div className="pointer-events-none fixed -bottom-32 -right-32 -z-10 h-96 w-96 rounded-full bg-indigo-600/20 blur-3xl" />

      {/* 촬영 플래시 */}
      {showFlash && (
        <div
          className="pointer-events-none fixed inset-0 z-50 bg-white"
          style={{ animation: 'flash-fade 0.35s ease-out' }}
        />
      )}

      {/* 콘텐츠가 화면보다 짧으면 세로 중앙, 길면 위에서부터 스크롤 (m-auto가 둘 다 처리) */}
      <div className="m-auto w-full max-w-6xl px-4 py-8">
        <header className="mb-8 text-center">
          <div className="mb-2 inline-flex items-center gap-2 rounded-full border border-white/10 bg-white/5 px-4 py-1.5 text-xs font-medium text-fuchsia-200 backdrop-blur">
            <Sparkles className="h-3.5 w-3.5" />
            실시간 웹캠 매직 필터
          </div>
          <h1 className="bg-gradient-to-r from-fuchsia-300 via-violet-200 to-sky-300 bg-clip-text text-4xl font-black tracking-tight text-transparent sm:text-5xl">
            웹캠 매직 필터 스튜디오
          </h1>
          <p className="mt-3 text-sm text-slate-400">
            14가지 효과를 입히고, 밝기·강도를 조절해 마음에 드는 순간을 사진·영상으로 남겨보세요.
          </p>
        </header>

        <div className="grid gap-6 lg:grid-cols-[1.6fr_1fr] lg:items-start">
          {/* 왼쪽: 미리보기 + 촬영 버튼 */}
          <div>
            <div className="relative aspect-video w-full overflow-hidden rounded-3xl border border-white/10 bg-black shadow-2xl shadow-black/50">
              <video ref={videoRef} className="hidden" playsInline muted />
              <canvas ref={canvasRef} className="h-full w-full object-cover" />

              {!isStreaming && (
                <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 bg-gradient-to-br from-slate-900 to-slate-950 text-slate-400">
                  <div className="flex h-20 w-20 items-center justify-center rounded-full bg-white/5 ring-1 ring-white/10">
                    <Camera className="h-9 w-9" />
                  </div>
                  <p className="text-sm">카메라가 꺼져 있어요</p>
                  <button
                    onClick={startCamera}
