              {/* 녹화 표시 */}
              {isRecording && (
                <div className="absolute left-4 top-4 flex items-center gap-2 rounded-full bg-red-500/90 px-3 py-1.5 text-xs font-bold shadow-lg backdrop-blur">
                  <span className="h-2.5 w-2.5 rounded-full bg-white" style={{ animation: 'pulse-rec 1s ease-in-out infinite' }} />
                  REC {formatTime(recordSeconds)}
