              {/* 현재 필터 배지 */}
              {isStreaming && (
                <div className="absolute right-4 top-4 flex items-center gap-1.5 rounded-full bg-black/40 px-3 py-1.5 text-xs font-medium backdrop-blur">
                  <span>{currentFilter.emoji}</span>
