              >
                <Camera className="h-5 w-5" /> 사진 찍기
                <kbd className="ml-1 hidden rounded bg-black/20 px-1.5 py-0.5 text-[10px] font-normal sm:inline">Space</kbd>
              </button>

              {isRecording ? (
                <button
                  onClick={stopRecording}
                  className="flex items-center gap-2 rounded-2xl bg-red-500 px-5 py-3.5 font-semibold shadow-lg shadow-red-500/30 transition hover:scale-[1.02]"
