                  <Square className="h-5 w-5" /> 녹화 멈춤
                </button>
              ) : (
                <button
                  onClick={startRecording}
                  disabled={!isStreaming}
                  className="flex items-center gap-2 rounded-2xl bg-rose-500/90 px-5 py-3.5 font-semibold shadow-lg shadow-rose-500/30 transition hover:scale-[1.02] disabled:cursor-not-allowed disabled:opacity-40 disabled:hover:scale-100"
                >
                  <Circle className="h-5 w-5" /> 녹화 시작
