                </button>
              )}
            </div>

            {/* 촬영 옵션: 거울 모드 + 타이머 */}
            <div className="mt-3 flex flex-wrap items-center gap-3">
              <button
                onClick={() => setMirror((value) => !value)}
                className={`flex items-center gap-2 rounded-xl px-4 py-2 text-sm font-medium transition ${
                  mirror ? 'bg-indigo-500/80 text-white' : 'bg-white/5 text-slate-300 hover:bg-white/10'
                }`}
              >
                <FlipHorizontal2 className="h-4 w-4" /> 거울 모드
              </button>

              <div className="flex items-center gap-1 rounded-xl bg-white/5 p-1">
                <span className="flex items-center gap-1 px-2 text-xs text-slate-400">
                  <Timer className="h-4 w-4" /> 타이머
                </span>
                {TIMER_OPTIONS.map((seconds) => (
                  <button
                    key={seconds}
                    onClick={() => setTimerSeconds(seconds)}
                    className={`rounded-lg px-3 py-1.5 text-xs font-semibold transition ${
                      timerSeconds === seconds ? 'bg-fuchsia-500 text-white' : 'text-slate-300 hover:bg-white/10'
                    }`}
                  >
                    {seconds === 0 ? '끄기' : `${seconds}초`}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* 오른쪽: 탭 메뉴 컨트롤 패널 (필터 / 보정 / 갤러리) */}
          <div className="flex flex-col overflow-hidden rounded-3xl border border-white/10 bg-white/5 backdrop-blur-xl">
            {/* 탭 바 */}
            <div className="flex gap-1 border-b border-white/10 p-2">
              {TABS.map((tab) => {
                const isActive = activeTab === tab.id;
                const TabIcon = tab.icon;
                return (
                  <button
                    key={tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`relative flex flex-1 items-center justify-center gap-1.5 rounded-2xl px-3 py-2.5 text-sm font-semibold transition ${
                      isActive
                        ? 'bg-white/10 text-white'
                        : 'text-slate-400 hover:bg-white/5 hover:text-white'
                    }`}
                  >
                    <TabIcon className="h-4 w-4" />
                    <span>{tab.label}</span>
                    {tab.id === 'gallery' && photos.length > 0 && (
                      <span className="ml-0.5 rounded-full bg-fuchsia-500 px-1.5 text-[10px] font-bold text-white">
                        {photos.length}
                      </span>
                    )}
                    {isActive && (
                      <span className="absolute inset-x-3 -bottom-[9px] h-0.5 rounded-full bg-gradient-to-r from-fuchsia-400 to-indigo-400" />
                    )}
                  </button>
                );
              })}
            </div>

            {/* 탭 내용 */}
            <div key={activeTab} className="min-h-[320px] flex-1 p-4" style={{ animation: 'fade-up 0.25s ease-out' }}>
              {/* 필터 탭 */}
              {activeTab === 'filter' && (
                <div className="grid grid-cols-4 gap-2 sm:grid-cols-5">
                  {FILTER_OPTIONS.map((option) => (
                    <FilterChip
                      key={option.id}
                      option={option}
                      isActive={activeFilter === option.id}
                      onSelect={setActiveFilter}
                    />
                  ))}
                </div>
              )}

              {/* 보정 탭 */}
              {activeTab === 'adjust' && (
                <div>
                  <div className="mb-4 flex justify-end">
                    <button
                      onClick={resetAdjustments}
                      className="flex items-center gap-1 rounded-lg bg-white/10 px-2.5 py-1 text-[11px] font-medium text-slate-300 transition hover:bg-white/20"
                    >
                      <RotateCcw className="h-3.5 w-3.5" /> 초기화
                    </button>
                  </div>
                  <div className="space-y-4">
                    <ControlSlider icon={<Sparkles className="h-3.5 w-3.5" />} label="필터 강도" value={intensity} min={0} max={100} color="#d946ef" disabled={!hasIntensity} onChange={setIntensity} />
                    <ControlSlider icon={<Sun className="h-3.5 w-3.5" />} label="밝기" value={adjust.brightness} min={50} max={150} color="#fbbf24" onChange={(value) => setAdjust((prev) => ({ ...prev, brightness: value }))} />
                    <ControlSlider icon={<Contrast className="h-3.5 w-3.5" />} label="대비" value={adjust.contrast} min={50} max={150} color="#38bdf8" onChange={(value) => setAdjust((prev) => ({ ...prev, contrast: value }))} />
                    <ControlSlider icon={<Droplet className="h-3.5 w-3.5" />} label="채도" value={adjust.saturation} min={0} max={200} color="#34d399" onChange={(value) => setAdjust((prev) => ({ ...prev, saturation: value }))} />
                  </div>
                </div>
              )}

              {/* 갤러리 탭 (녹화한 영상 + 사진) */}
              {activeTab === 'gallery' && (
                <div className="space-y-5">
                  {recordedUrl && (
                    <div>
                      <h2 className="mb-2 flex items-center gap-2 text-sm font-semibold text-slate-200">
                        <Film className="h-4 w-4 text-rose-300" /> 녹화한 영상
                      </h2>
                      <video src={recordedUrl} controls className="w-full rounded-2xl border border-white/10 bg-black" />
                      <a
                        href={recordedUrl}
                        download="webcam-magic.webm"
                        className="mt-2 flex items-center justify-center gap-2 rounded-2xl bg-white/10 px-5 py-2.5 text-sm font-medium transition hover:bg-white/20"
                      >
                        <Download className="h-4 w-4" /> 영상 다운로드
                      </a>
                    </div>
                  )}
                  <Gallery
                    photos={photos}
                    onView={setViewingPhoto}
                    onDownloadAll={downloadAllPhotos}
                    onClear={() => setPhotos([])}
                  />
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 사진 크게 보기 */}
      {viewingPhoto && (
        <PhotoModal
          photo={viewingPhoto}
          onClose={() => setViewingPhoto(null)}
          onDownload={downloadPhoto}
          onDelete={deletePhoto}
        />
      )}
    </div>
  );
}

// 픽셀 반복문 대신 GPU가 처리하는 SVG 필터 정의 (만화·네온)
// 캔버스에서 ctx.filter = 'url(#magic-edge)' 처럼 참조해서 쓴다.
function SvgFilters() {
  return (
    <svg aria-hidden="true" width="0" height="0" style={{ position: 'absolute' }}>
      <defs>
        {/* 만화: 색을 몇 단계로 뭉뚱그려 포스터처럼 단순화 */}
        <filter id="magic-posterize">
          <feComponentTransfer>
            <feFuncR type="discrete" tableValues="0 0.25 0.5 0.75 1" />
            <feFuncG type="discrete" tableValues="0 0.25 0.5 0.75 1" />
            <feFuncB type="discrete" tableValues="0 0.25 0.5 0.75 1" />
          </feComponentTransfer>
        </filter>
        {/* 네온: 흑백 → 윤곽선 검출(feConvolveMatrix) → 형광색으로 강조 */}
        <filter id="magic-edge">
          <feColorMatrix
            type="matrix"
            values="0.33 0.33 0.33 0 0  0.33 0.33 0.33 0 0  0.33 0.33 0.33 0 0  0 0 0 1 0"
            result="gray"
          />
          <feConvolveMatrix
            in="gray"
            order="3"
            preserveAlpha="true"
            kernelMatrix="0 -1 0 -1 4 -1 0 -1 0"
            result="edges"
          />
          <feComponentTransfer in="edges">
            <feFuncR type="linear" slope="0.4" />
            <feFuncG type="linear" slope="1.6" />
            <feFuncB type="linear" slope="2.4" />
          </feComponentTransfer>
        </filter>
      </defs>
    </svg>
  );
}

